<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/pdf_documents.php';
$id=max(0,(int)($_GET['id']??$_POST['id']??0));require_permission($id?'contracts.edit':'contracts.create');$contract=null;if($id){$stmt=db()->prepare('SELECT * FROM contracts WHERE id=?');$stmt->execute([$id]);$contract=$stmt->fetch();if(!$contract){http_response_code(404);exit('Contrato no encontrado.');}if(!in_array($contract['status'],['draft','rejected'],true)){flash('error','Solo se pueden editar contratos en borrador o rechazados.');redirect('contract_view.php?id='.$id);}}
$clients=db()->query("SELECT * FROM clients WHERE status<>'inactive' OR id=".(int)($contract['client_id']??0)." ORDER BY COALESCE(NULLIF(country,''),'Sin país'),company_name")->fetchAll();$users=db()->query("SELECT id,name,email FROM users WHERE is_active=1 ORDER BY name")->fetchAll();$templates=db()->query("SELECT * FROM contract_templates WHERE is_active=1".($contract&&$contract['template_id']?' OR id='.(int)$contract['template_id']:'')." ORDER BY sort_order,language,name")->fetchAll();$pageTitle=$contract?'Editar contrato':'Nuevo contrato';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$clientId=max(0,(int)($_POST['client_id']??0));$ownerUserId=max(0,(int)($_POST['owner_user_id']??$_SESSION['user_id']))?:null;$templateId=max(0,(int)($_POST['template_id']??0))?:null;$title=trim((string)($_POST['title']??''));$language=(string)($_POST['language']??'es');$recipientName=trim((string)($_POST['recipient_name']??''));$recipientEmail=strtolower(trim((string)($_POST['recipient_email']??'')));$content=trim((string)($_POST['content']??''));$issueDate=(string)($_POST['issue_date']??date('Y-m-d'));if(!in_array($language,['es','pt','en'],true))$language='es';if($clientId<1)$errors[]='Selecciona un cliente.';if($title==='')$errors[]='El título es obligatorio.';if(strlen($content)<50)$errors[]='El contrato debe tener al menos 50 caracteres.';if($recipientEmail!==''&&!filter_var($recipientEmail,FILTER_VALIDATE_EMAIL))$errors[]='El email no es válido.';if(!$errors){$pdo=db();if($id){$pdo->prepare('UPDATE contracts SET client_id=?,owner_user_id=?,template_id=?,title=?,language=?,recipient_name=?,recipient_email=?,content=?,issue_date=?,status=\'draft\' WHERE id=?')->execute([$clientId,$ownerUserId,$templateId,$title,$language,$recipientName,$recipientEmail,$content,$issueDate,$id]);flash('success','Contrato actualizado.');}else{$token=bin2hex(random_bytes(32));$tmp='TMP-'.bin2hex(random_bytes(8));$pdo->prepare('INSERT INTO contracts(contract_number,client_id,owner_user_id,template_id,title,language,recipient_name,recipient_email,content,status,public_token,issue_date,created_by) VALUES (?,?,?,?,?,?,?,?,?,\'draft\',?,?,?)')->execute([$tmp,$clientId,$ownerUserId,$templateId,$title,$language,$recipientName,$recipientEmail,$content,$token,$issueDate,$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();$number=(string)setting('contract_prefix','CON').'-'.date('Y',strtotime($issueDate)).'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE contracts SET contract_number=? WHERE id=?')->execute([$number,$id]);flash('success','Contrato creado. Revísalo antes de enviarlo.');}log_activity('Contrato guardado',$clientId,null,$title);redirect('contract_view.php?id='.$id);}}
$v=fn(string$key,mixed$default='')=>$_POST[$key]??($contract[$key]??$default);$templateJson=[];foreach($templates as$t)$templateJson[(string)$t['id']]=$t;$clientJson=[];foreach($clients as$c)$clientJson[(string)$c['id']]=$c;$providerJson=['company'=>(string)setting('contract_company_name','SÓCRATES ONE · Creative Studio'),'id'=>(string)setting('contract_company_id',''),'address'=>(string)setting('contract_company_address','')];require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel" data-contract-form><div class="panel-header"><div><h2><?=$contract?'Actualizar contrato':'Crear contrato desde una plantilla'?></h2><span class="table-sub">El contenido queda guardado como una copia editable y no cambia si luego modificas la plantilla.</span></div><a class="btn btn-light btn-small" href="contracts.php">Cancelar</a></div><div class="panel-body form-grid three"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Cliente *<select name="client_id" required data-contract-client><option value="">Seleccionar...</option><?php foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=((int)$v('client_id')===(int)$c['id'])?'selected':''?>><?=e(($c['country']?:'Sin país').' · '.$c['company_name'])?></option><?php endforeach;?></select></label><label>Responsable<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=(int)$u['id']?>" <?=((int)$v('owner_user_id',(int)$_SESSION['user_id'])===(int)$u['id'])?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Plantilla<select name="template_id" data-contract-template><option value="">Documento en blanco</option><?php foreach($templates as$t):?><option value="<?=(int)$t['id']?>" <?=((int)$v('template_id')===(int)$t['id'])?'selected':''?>><?=e(language_label($t['language']).' · '.$t['name'])?></option><?php endforeach;?></select></label><label>Fecha<input type="date" name="issue_date" value="<?=e($v('issue_date',date('Y-m-d')))?>"></label><label>Idioma<select name="language" data-contract-language><option value="es" <?=$v('language','es')==='es'?'selected':''?>>Español</option><option value="pt" <?=$v('language')==='pt'?'selected':''?>>Português</option><option value="en" <?=$v('language')==='en'?'selected':''?>>English</option></select></label><label>Nombre del destinatario<input name="recipient_name" data-contract-recipient value="<?=e($v('recipient_name'))?>"></label><label>Email del destinatario<input type="email" name="recipient_email" data-contract-email value="<?=e($v('recipient_email'))?>"></label><label class="full">Título *<input name="title" required data-contract-title value="<?=e($v('title'))?>"></label><div class="full actions"><button type="button" class="btn btn-secondary btn-small" data-apply-contract-template>APLICAR PLANTILLA Y DATOS DEL CLIENTE</button><a class="btn btn-light btn-small" href="contract_templates.php" target="_blank">Administrar plantillas</a></div><label class="full">Contenido del contrato *<textarea name="content" rows="28" required data-contract-content><?=e($v('content'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="contracts.php">Cancelar</a><button class="btn btn-primary">GUARDAR CONTRATO</button></div></div></form><script type="application/json" id="contract-template-data"><?=json_encode($templateJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><script type="application/json" id="contract-client-data"><?=json_encode($clientJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><script type="application/json" id="contract-provider-data"><?=json_encode($providerJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><script>(()=>{const f=document.querySelector('[data-contract-form]');if(!f)return;const ts=JSON.parse(document.getElementById('contract-template-data').textContent||'{}'),cs=JSON.parse(document.getElementById('contract-client-data').textContent||'{}'),provider=JSON.parse(document.getElementById('contract-provider-data').textContent||'{}');const client=f.querySelector('[data-contract-client]'),template=f.querySelector('[data-contract-template]'),content=f.querySelector('[data-contract-content]'),title=f.querySelector('[data-contract-title]'),lang=f.querySelector('[data-contract-language]'),recipient=f.querySelector('[data-contract-recipient]'),email=f.querySelector('[data-contract-email]');const apply=()=>{const t=ts[template.value],c=cs[client.value];if(!t){return;}let body=t.content||'';const rep={'{{EMPRESA_PRESTADORA}}':provider.company||'','{{ID_PRESTADOR}}':provider.id||'','{{DIRECCION_PRESTADOR}}':provider.address||'','{{CLIENTE}}':c?.company_name||'','{{ID_CLIENTE}}':c?.tax_id||'','{{PAIS}}':c?.country||'','{{DIRECCION_CLIENTE}}':[c?.address,c?.city,c?.country].filter(Boolean).join(', '),'{{CONTACTO}}':c?.contact_name||'','{{EMAIL_CLIENTE}}':c?.email||'','{{SERVICIOS}}':'____________________________','{{VALOR}}':'____________________________','{{FECHA_INICIO}}':new Date().toLocaleDateString('es-CL'),'{{FECHA}}':new Date().toLocaleDateString('es-CL')};Object.entries(rep).forEach(([k,v])=>body=body.split(k).join(v));content.value=body;title.value=t.title||'';lang.value=t.language||'es';if(c){recipient.value=recipient.value||c.contact_name||'';email.value=email.value||c.email||'';}};f.querySelector('[data-apply-contract-template]').addEventListener('click',apply);client.addEventListener('change',()=>{const c=cs[client.value];if(c){recipient.value=c.contact_name||'';email.value=c.email||'';}});})();</script><?php require __DIR__.'/includes/footer.php';?>
